import{_ as t,o as a,c as r,ak as i}from"./chunks/framework.Cp-g6eQj.js";const g=JSON.parse('{"title":"Overview","description":"","frontmatter":{},"headers":[],"relativePath":"introduction/overview.md","filePath":"introduction/overview.md","lastUpdated":1778472767000}'),o={name:"introduction/overview.md"};function n(s,e,l,d,h,c){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to “Overview”">​</a></h1><p>An overview on the origin and the purpose of NBCL.</p><h2 id="origin" tabindex="-1">Origin <a class="header-anchor" href="#origin" aria-label="Permalink to “Origin”">​</a></h2><p>NBCL was made for a purpose and it solves a very specific problem. The language space in the Rust community is limited. Only a few languages like <a href="https://rune-rs.github.io" target="_blank" rel="noreferrer">Rune</a>, <a href="https://rhai.rs" target="_blank" rel="noreferrer">Rhai</a>, and <a href="https://koto.dev" target="_blank" rel="noreferrer">Koto</a> exists. And almost all of them either are made for only scripting purposes, has terrible error reporting, or has a syntax that feels like JSON for configuring.</p><p>And if you look outside the Rust ecosystem, you&#39;ll see languages like HCL, KCL, Jsonnet, etc. But most of them are made for cloud purposes, sometimes has quite terrible syntax, or that most of them are written in <a href="https://go.dev/" target="_blank" rel="noreferrer">Golang</a> and requires FFI to function in Rust.</p><p>So, NBCL now exists to solve this problem. It takes the HCL-like blocky configuration syntax and adds its own scripting syntax to create the ideal solution. It is made to address all the pain points, and thus it ships with detailed error structures with all the cruical data that can be extracted and passed directly into any diagnostic tool like <a href="https://crates.io/crates/ariadne" target="_blank" rel="noreferrer">ariadne</a>, or <a href="https://crates.io/crates/codespan-reporting" target="_blank" rel="noreferrer">codespan-reporting</a>.</p><h2 id="what-it-is-and-is-not" tabindex="-1">What it is and is not <a class="header-anchor" href="#what-it-is-and-is-not" aria-label="Permalink to “What it is and is not”">​</a></h2><p>NBCL is a <strong>configuration language</strong> with <strong>scripting capabilities</strong>. Unlike pure configuration formats like JSON, or TOML, it can produce side effects alongside resolving into data. This makes it especially useful for large configs, defining UI components, or anywhere you need an extensible scripting language that happens to prioritize configuration by default.</p><p>That said, NBCL is not the right tool for every job. It is best when both of its configuration and scripting capabilities are used together. If you <strong>only</strong> need pure scripting, go for a language like <a href="https://crates.io/crates/rhai" target="_blank" rel="noreferrer">rhai</a>, and if you <strong>only</strong> need pure static configuration, go for a language like TOML.</p>',9)])])}const f=t(o,[["render",n]]);export{g as __pageData,f as default};
